<div class="row g-3"><div class="col-lg-5">
<?php if ($manage): ?><form class="card-s mb-3" method="post" action="<?= url('api/v1/school/facilities') ?>" data-ajax data-reload novalidate><?= csrf_field() ?><h2 class="h6">مرفق جديد</h2><div class="row g-2"><div class="col-12"><input class="form-control" name="name" placeholder="الاسم (مختبر، قاعة…)" aria-label="الاسم" required></div><div class="col-6"><input class="form-control" name="kind" placeholder="النوع" aria-label="النوع"></div><div class="col-6"><input class="form-control" name="capacity" type="number" min="1" placeholder="السعة" aria-label="السعة"></div><input type="hidden" name="status" value="available"><div class="col-12"><button class="btn btn-primary w-100">إضافة</button></div></div></form><?php endif; ?>
<form class="card-s" method="post" action="<?= url('api/v1/school/bookings') ?>" data-ajax data-reload novalidate><?= csrf_field() ?><h2 class="h6">حجز جديد</h2>
 <select class="form-select mb-2" name="facility_id" aria-label="المرفق" required><option value="">اختر المرفق</option><?php foreach ($rows as $f): if ($f['status'] === 'available'): ?><option value="<?= (int)$f['id'] ?>"><?= e($f['name']) ?></option><?php endif; endforeach; ?></select>
 <div class="row g-2 mb-2"><div class="col"><label class="form-label" for="b1">من</label><input class="form-control" type="datetime-local" id="b1" name="starts_at" required></div><div class="col"><label class="form-label" for="b2">إلى</label><input class="form-control" type="datetime-local" id="b2" name="ends_at" required></div></div>
 <input class="form-control mb-2" name="purpose" placeholder="الغرض" aria-label="الغرض"><button class="btn btn-primary w-100">حجز</button></form></div>
<div class="col-lg-7"><div class="card-s mb-3"><h2 class="h6">المرافق</h2><?php if (!$rows): ?><div class="empty-state">لا مرافق.</div><?php endif; ?>
<?php foreach ($rows as $f): ?><div class="d-flex justify-content-between border-bottom py-1"><span><?= e($f['name']) ?> <small class="text-muted"><?= e($f['kind'] ?? '') ?><?= $f['capacity'] ? ' · ' . (int)$f['capacity'] . ' مقعد' : '' ?></small> <?= $f['status'] === 'maintenance' ? '<span class="badge text-bg-warning">صيانة</span>' : '' ?></span>
 <?php if ($manage): ?><span class="d-flex gap-1"><button class="btn btn-sm btn-outline-secondary" data-api="<?= url('api/v1/school/facilities/' . (int)$f['id']) ?>" data-method="PUT" data-body='<?= e(json_encode(['name' => $f['name'], 'kind' => $f['kind'], 'capacity' => (string)$f['capacity'], 'status' => $f['status'] === 'available' ? 'maintenance' : 'available'], JSON_UNESCAPED_UNICODE)) ?>'><?= $f['status'] === 'available' ? 'صيانة' : 'إتاحة' ?></button><button class="btn btn-sm btn-outline-danger" data-api="<?= url('api/v1/school/facilities/' . (int)$f['id']) ?>" data-method="DELETE" data-confirm="حذف المرفق؟"><i class="bi bi-trash"></i></button></span><?php endif; ?></div><?php endforeach; ?></div>
<div class="card-s"><form method="get" class="d-flex gap-2 mb-2"><input class="form-control form-control-sm w-auto" type="date" name="day" value="<?= e($day) ?>" data-autosubmit aria-label="اليوم"></form><h2 class="h6">حجوزات <?= e($day) ?></h2><?php if (!$bookings): ?><div class="text-muted small">لا حجوزات.</div><?php endif; ?>
<?php foreach ($bookings as $b): ?><div class="d-flex justify-content-between border-bottom py-1"><span><strong><?= e($b['facility']) ?></strong> <?= e(substr($b['starts_at'], 11, 5)) ?>–<?= e(substr($b['ends_at'], 11, 5)) ?> <small class="text-muted"><?= e($b['booker']) ?> <?= e($b['purpose'] ?? '') ?></small></span><?php if ($manage || (int)$b['booked_by'] === (int)$me): ?><button class="btn btn-sm btn-outline-danger" data-api="<?= url('api/v1/school/bookings/' . (int)$b['id']) ?>" data-method="DELETE" data-confirm="إلغاء الحجز؟">إلغاء</button><?php endif; ?></div><?php endforeach; ?></div></div></div>
